<?php
declare(strict_types=1);
function moments_routes(PDO $db,array $auth,string $path,string $method): bool {
 if(!preg_match('~^/api/moments(?:/([0-9A-HJKMNP-TV-Z]{26}))?$~',$path,$match))return false;$id=$match[1]??null;$uid=$auth['user']['id'];
 if($method==='GET'){$cursor=$_GET['cursor']??'';$track=$_GET['trackId']??null;if($cursor!==''&&!preg_match('/^[0-9A-HJKMNP-TV-Z]{26}$/D',$cursor)||$track!==null&&!preg_match('/^[0-9A-HJKMNP-TV-Z]{26}$/D',$track))fail('validation','Invalid moment filter.');$rows=query_all($db,"SELECT m.* FROM moments m JOIN tracks t ON t.id=m.track_id WHERE m.user_id=? AND m.deleted=0 AND t.deleted=0 AND(t.owner_id=? OR t.visibility='public') AND m.id>? AND(? IS NULL OR m.track_id=?) AND(? IS NULL OR m.id=?) ORDER BY m.id LIMIT 501",[$uid,$uid,$cursor,$track,$track,$id,$id]);if($id&&!$rows)fail('not_found','Moment not found.',404);reply($id?['moment'=>$rows[0]]:['items'=>array_slice($rows,0,500),'nextCursor'=>count($rows)>500?$rows[499]['id']:null]);}
 if(!in_array($method,['POST','PATCH','DELETE'],true)||!$id&&$method!=='POST'||$id&&$method==='POST')return false;
 $raw=str_contains($_SERVER['CONTENT_TYPE']??'','application/json')?body():[];
 $result=transaction($db,function()use($db,$auth,$id,$uid,$method,$raw){$before=$id?query_one($db,'SELECT * FROM moments WHERE id=? AND user_id=? AND deleted=0',[$id,$uid]):null;if($id&&!$before)fail('not_found','Moment not found.',404);$track=readable_track($db,$auth,(string)($before['track_id']??$raw['trackId']??''));if(array_key_exists('expectedRev',$raw)&&(!is_int($raw['expectedRev'])||$raw['expectedRev']!==($before['rev']??null)))fail('conflict','This moment changed. Reload before editing it.',409);$at=$before['at_ms']??0;$label=$before['label']??'';
 if($method!=='DELETE'){if(!$id||array_key_exists('atMs',$raw))$at=playback_integer($raw['atMs']??null,'Moment position',(int)$track['duration_ms']);if(!$id||array_key_exists('label',$raw))$label=input_text($raw['label']??null,'Moment label',200)??'';}
 $momentId=$id??ulid();$rev=next_rev($db);if($id)execute($db,'UPDATE moments SET at_ms=?,label=?,deleted=?,rev=? WHERE id=? AND user_id=?',[$at,$label,$method==='DELETE'?1:0,$rev,$id,$uid]);else execute($db,'INSERT INTO moments(id,user_id,track_id,at_ms,label,created_at,rev,deleted) VALUES(?,?,?,?,?,?,?,0)',[$momentId,$uid,$track['id'],$at,$label,now_ms(),$rev]);execute($db,"INSERT INTO changes(id,user_id,actor,token_name,session_label,summary,ops,created_at,undoable) VALUES(?,?,?,?,?,?,'[]',?,0)",[ulid(),$uid,isset($auth['token'])?'api':'web',$auth['token']['name']??null,$auth['session']['device_label'],($method==='DELETE'?'Deleted':($id?'Updated':'Saved')).' a moment',now_ms()]);return query_one($db,'SELECT * FROM moments WHERE id=?',[$momentId]);});reply(['moment'=>$result],$id?200:201);
}
